async function invoicesList(){const l=await api('/me/invoices');app.innerHTML=`<h2>فواتيري</h2><div class=panel>${l.map(x=>`<a class=row href="#/invoice/${x.id}"><span>${INV_KIND[x.kind]||'وثيقة'} ${esc(x.ref)}<br><small>${esc(x.issuer_name||'')} ← ${esc(x.buyer_name||'')}</small></span><small>${Number(x.total).toFixed(2)} ريال</small></a>`).join('')||'<div class=empty>لا توجد فواتير بعد.</div>'}</div>`}
async function invoiceView(id){const r=await api('/invoices/'+id);const money=n=>Number(n||0).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})+' ريال';const isSale=/^S-/.test(r.ref);const comm=r.commission!=null?r.commission:Math.round(r.subtotal*r.commission_pct)/100;const net=Math.round((r.subtotal-comm)*100)/100;const date=String(r.issued_at||'').slice(0,10);const hp=r.helper_party||{},cp=r.client_party||{};
const party=(t,p)=>`<div class=ivp><h4>${t}</h4><b>${esc(p.name||'—')}</b>${p.city?`<small>${esc(p.city)}</small>`:''}${p.phone?`<small>الجوال: <bdi dir=ltr>${esc(p.phone)}</bdi></small>`:''}${p.email?`<small>البريد: <bdi dir=ltr>${esc(p.email)}</bdi></small>`:''}</div>`;
const logo=r.logo_id?`<img class=ivlogo src="/api/files/${+r.logo_id}" alt="شعار مقدم الخدمة">`:`<div class=ivlogo-ph>${esc((hp.name||'م').charAt(0))}</div>`;
const clauses=['يلتزم مقدم الخدمة بتنفيذ الخدمة الموضحة أعلاه وفق ما اتفق عليه الطرفان عبر المنصة.','يُسدَّد المبلغ المتفق عليه عبر منصة المساعد، ويُعد هذا المستند إثباتًا للمعاملة.','تُعد الخدمة منجزة بعد تأكيد العميل للإنجاز، أو بعد انتهاء مهلة التأكيد وفق سياسة المنصة.','أي اعتراض على الخدمة يُقدَّم خلال المهلة المحددة عبر صفحة الاتفاق، وتراجعه المنصة.','عمولة المنصة تُخصم من المبلغ وفق نسبتها المعلنة، ولا تُحمَّل على العميل.','تسري سياسة الإلغاء المعلنة في المنصة على هذا الاتفاق.'];
app.innerHTML=`<style>
.ivdoc{background:#fff;border:1px solid #e3e7e5;border-radius:16px;padding:20px;direction:rtl;color:#111}
.ivhead{display:flex;align-items:center;gap:14px;border-bottom:2px solid #1f5f4a;padding-bottom:12px}
.ivlogo{width:72px;height:72px;object-fit:contain;border-radius:12px;background:#f6f8f7}
.ivlogo-ph{width:72px;height:72px;border-radius:12px;background:#1f5f4a;color:#fff;display:grid;place-items:center;font-size:30px;font-weight:700}
.ivtitle{display:flex;flex-direction:column;gap:2px}.ivtitle h2{margin:0;color:#1f5f4a}.ivtitle small{color:#5f6f68}
.ivparties{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:14px 0}
.ivp{background:#f6f8f7;border-radius:12px;padding:10px;display:flex;flex-direction:column;gap:3px}.ivp h4{margin:0 0 4px;color:#1f5f4a;font-size:14px}
.ivsec{margin:12px 0}.ivsec h4{margin:0 0 6px;color:#1f5f4a}
.ivnotes{background:#f6f8f7;border:1px dashed #b9c9c1;border-radius:12px;padding:12px;min-height:70px;line-height:1.9;white-space:normal}
.ivt{width:100%;border-collapse:collapse;margin-top:10px}.ivt td{padding:9px 6px;border-bottom:1px solid #e3e7e5}.ivt td+td{text-align:left}.ivt .tot td{background:#e7f5ee;border-bottom:0}
.ivsplit{font-size:13px;color:#5f6f68;margin-top:8px;display:flex;flex-direction:column;gap:2px}
.ivcl{padding-inline-start:20px;line-height:1.9;font-size:14px;margin:0}
.ivfoot{margin-top:14px;color:#8a938f;font-size:12px}
@media print{body *{visibility:hidden}#invDoc,#invDoc *{visibility:visible}#invDoc{position:absolute;inset:0 0 auto 0;border:0;padding:0}.noprint{display:none!important}}
</style>
<section class=ivdoc id=invDoc>
<header class=ivhead>${logo}<div class=ivtitle><h2>${esc(INV_KIND[r.kind]||'وثيقة')}</h2><small>رقم: ${esc(r.ref)}</small><small>التاريخ: ${esc(date)}</small></div></header>
<div class=ivparties>${party('مقدم الخدمة',hp)}${party('العميل',cp)}</div>
<div class=ivsec><h4>تفاصيل الخدمة</h4><p>${esc(r.service_desc||r.description||'')}</p></div>
<div class=ivsec><h4>معلومات وقطع الصيانة</h4><div class=ivnotes>${r.notes?esc(r.notes).replace(/\n/g,'<br>'):'<small>لا توجد تفاصيل مضافة.</small>'}</div></div>
<table class=ivt><tr><td>قيمة الخدمة قبل الضريبة</td><td>${money(r.subtotal)}</td></tr><tr><td>ضريبة القيمة المضافة (${Math.round(r.vat_rate*100)}%)</td><td>${money(r.vat_amount)}</td></tr><tr class=tot><td><b>الإجمالي شامل الضريبة</b></td><td><b>${money(r.total)}</b></td></tr></table>
${isSale?`<div class=ivsplit><b>توزيع المبلغ</b><small>عمولة المنصة (${r.commission_pct}%): ${money(comm)} · صافي مقدم الخدمة: ${money(net)}</small></div>`:''}
${isSale?`<div class=ivsec><h4>البنود</h4><ol class=ivcl>${clauses.map(c=>`<li>${esc(c)}</li>`).join('')}</ol></div>`:''}
<footer class=ivfoot>${r.qr?'رمز QR محفوظ، ويُعرض عند تفعيل الربط مع الفوترة الإلكترونية.':''}</footer>
</section>
<div class="inv-actions noprint"><button class=btn id=invPrint type=button>تحميل / حفظ PDF</button><a class=lnk href="#/invoices">‹ فواتيري</a></div>`;
$('#invPrint').onclick=()=>window.print()}
async function notifs(){const l=await api('/notifications');app.innerHTML=`<h2>الإشعارات</h2><div class=panel>${l.map(n=>`<a class=row href="${esc(n.link||'#/notifs')}"><span>${esc(n.text)}${n.read?'':' •'}</span><small>${n.created_at.slice(0,16)}</small></a>`).join('')||'<div class=empty>لا توجد إشعارات.</div>'}</div>`;me.unread=0;nav()}

