  box.innerHTML+=me.user?`<form data-cform="${id}" class=form style="margin-top:8px;display:flex;gap:6px"><input name=body maxlength=300 required placeholder="اكتب تعليقًا..." style="flex:1"><button class=btn type=submit>إرسال</button></form>`:'';
  box.querySelectorAll('[data-kdel]').forEach(bt=>bt.onclick=async()=>{if(!confirm('حذف التعليق؟'))return;try{await api('/feed/comments/'+bt.dataset.kdel+'/delete','POST');await loadComments(id);bumpCount(id,-1)}catch(x){toast(x.message,1)}});
