  if(bt.dataset.frep){if(!confirm('الإبلاغ عن هذا المنشور؟'))return;try{const r=await api('/feed/'+bt.dataset.frep+'/report','POST');toast(r.hidden?'تم إخفاء المنشور للمراجعة':'شكرًا، تم استلام البلاغ')}catch(x){toast(x.message,1)}return}
